// App icon image for the chosen icon color: the heart over its background.

import { ICON_VARIANTS, DEFAULT_ICON_VARIANT } from './SparkleIcon.constants'

// Images generated by scripts/generate-icon.mjs, keyed by file name.
const IMAGES = Object.fromEntries(
  Object.entries(
    import.meta.glob('@/assets/icons/*.webp', { eager: true, query: '?url', import: 'default' })
  ).map(([path, url]) => [path.split('/').pop(), url])
)

export function SparkleIcon({ palette = DEFAULT_ICON_VARIANT, size = 200 }) {
  const variant = ICON_VARIANTS[palette] ?? ICON_VARIANTS[DEFAULT_ICON_VARIANT]

  return (
    <img
      src={IMAGES[variant.image]}
      alt=""
      width={size}
      height={size}
      style={{ borderRadius: '22%' }}
    />
  )
}
